// Match requirements to products from catalog
const requirements = $input.first().json.requirements;
const catalog = JSON.parse($input.item.json.data.toString());
const preferredManufacturer = 'ruckus'; // Can be made dynamic

const bom = {
  primary: [],
  alternative_ruckus: [],
  alternative_extreme: [],
  alternative_ubiquiti: []
};

function findBestMatch(requirement, manufacturer) {
  const category = requirement.category.toLowerCase();
  const products = catalog.manufacturers[manufacturer]?.categories[category] || [];

  if (products.length === 0) return null;

  // Simple matching - in production, use more sophisticated logic
  // based on specs, quantity, and requirements
  const match = products.find(p => {
    if (!p.erate_eligible) return false;

    // Check if specs match requirement specifications
    const reqSpecs = requirement.specifications.toLowerCase();
    const prodDesc = p.description.toLowerCase();

    // Basic matching on key terms
    if (reqSpecs.includes('poe') && !prodDesc.includes('poe')) return false;
    if (reqSpecs.includes('24-port') && p.specs.ports !== 24) return false;
    if (reqSpecs.includes('48-port') && p.specs.ports !== 48) return false;

    return true;
  });

  return match || products[0]; // Fallback to first product
}

// Generate BOM for each requirement
requirements.forEach(req => {
  // Primary recommendation (Ruckus)
  const ruckusProduct = findBestMatch(req, 'ruckus');
  if (ruckusProduct) {
    bom.primary.push({
      requirement: req.specifications,
      quantity: req.quantity,
      manufacturer: 'Ruckus',
      model: ruckusProduct.model,
      description: ruckusProduct.description,
      partNumber: ruckusProduct.part_number,
      unitPrice: ruckusProduct.price_range,
      specs: ruckusProduct.specs
    });
  }

  // Alternative: Extreme
  const extremeProduct = findBestMatch(req, 'extreme');
  if (extremeProduct) {
    bom.alternative_extreme.push({
      requirement: req.specifications,
      quantity: req.quantity,
      manufacturer: 'Extreme',
      model: extremeProduct.model,
      description: extremeProduct.description,
      partNumber: extremeProduct.part_number,
      unitPrice: extremeProduct.price_range,
      specs: extremeProduct.specs
    });
  }

  // Alternative: Ubiquiti
  const ubiquitiProduct = findBestMatch(req, 'ubiquiti');
  if (ubiquitiProduct) {
    bom.alternative_ubiquiti.push({
      requirement: req.specifications,
      quantity: req.quantity,
      manufacturer: 'Ubiquiti',
      model: ubiquitiProduct.model,
      description: ubiquitiProduct.description,
      partNumber: ubiquitiProduct.part_number,
      unitPrice: ubiquitiProduct.price_range,
      specs: ubiquitiProduct.specs
    });
  }
});

return [{
  json: {
    applicationNumber: $input.first().json.applicationNumber,
    applicantName: $input.first().json.applicantName,
    state: $input.first().json.state,
    requirements: requirements,
    bom: bom,
    generatedAt: new Date().toISOString()
  }
}];

