// Parse Claude API response and add recommendations to BOM
const apiResponse = $input.item.json;
const aiResponse = apiResponse.content[0].text;
let recommendations;

try {
  const jsonMatch = aiResponse.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    recommendations = JSON.parse(jsonMatch[1]);
  } else {
    recommendations = JSON.parse(aiResponse);
  }
} catch (error) {
  recommendations = {
    notes: aiResponse
  };
}

return [{
  json: {
    ...$input.item.json,
    aiRecommendations: recommendations,
    readyForProposal: true
  }
}];
